function Get-RelativePath {
    param(
        [string]$BasePath,
        [string]$TargetPath
    )

    $base = [System.IO.Path]::GetFullPath($BasePath)
    $target = [System.IO.Path]::GetFullPath($TargetPath)
    $baseTrimmed = $base.TrimEnd('\')
    $targetTrimmed = $target.TrimEnd('\')

    if ($targetTrimmed.Equals($baseTrimmed, [System.StringComparison]::OrdinalIgnoreCase)) {
        return "."
    }

    $basePrefix = $baseTrimmed + '\'
    if ($target.StartsWith($basePrefix, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $target.Substring($basePrefix.Length)
    }

    $baseUri = New-Object System.Uri(($baseTrimmed + '\'))
    $targetUri = New-Object System.Uri($target)
    $relative = $baseUri.MakeRelativeUri($targetUri).ToString()
    return [System.Uri]::UnescapeDataString($relative).Replace('/', '\')
}

function New-NormalizedKey {
    param([string]$Text)

    if ([string]::IsNullOrWhiteSpace($Text)) {
        return ""
    }

    $normalized = $Text.Normalize([Text.NormalizationForm]::FormD)
    $sb = New-Object System.Text.StringBuilder
    foreach ($ch in $normalized.ToCharArray()) {
        $category = [Globalization.CharUnicodeInfo]::GetUnicodeCategory($ch)
        if ($category -ne [Globalization.UnicodeCategory]::NonSpacingMark) {
            [void]$sb.Append($ch)
        }
    }

    $result = $sb.ToString().Normalize([Text.NormalizationForm]::FormC).ToLowerInvariant()
    $result = [regex]::Replace($result, "\s+", " ").Trim()
    return $result
}

function Resolve-WikiLinkCandidates {
    param(
        [string]$LinkTarget,
        [string]$CurrentDirectory,
        [System.Collections.Generic.HashSet[string]]$MarkdownPathSet,
        [hashtable]$StemIndex
    )

    $coreTarget = $LinkTarget.Split("#")[0].Split("|")[0].Trim()
    if ([string]::IsNullOrWhiteSpace($coreTarget)) {
        return @()
    }

    $candidates = New-Object System.Collections.Generic.List[string]
    $pathVariant = $coreTarget.Replace('/', '\')

    if ($pathVariant -match '\.[^\\\/]+$') {
        try {
            $candidatePath = [System.IO.Path]::GetFullPath((Join-Path $CurrentDirectory $pathVariant))
            if ($MarkdownPathSet.Contains($candidatePath)) {
                $candidates.Add($candidatePath)
            }
        } catch {
            return @()
        }
    } else {
        try {
            $candidatePath = [System.IO.Path]::GetFullPath((Join-Path $CurrentDirectory ($pathVariant + ".md")))
            if ($MarkdownPathSet.Contains($candidatePath)) {
                $candidates.Add($candidatePath)
            }
        } catch {
            return @()
        }

        $leaf = Split-Path $pathVariant -Leaf
        $normalizedLeaf = New-NormalizedKey $leaf
        if ($StemIndex.ContainsKey($normalizedLeaf)) {
            foreach ($match in $StemIndex[$normalizedLeaf]) {
                if (-not $candidates.Contains($match)) {
                    $candidates.Add($match)
                }
            }
        }
    }

    return $candidates
}

