from __future__ import annotations

import argparse
import re
from collections import Counter, defaultdict
from dataclasses import dataclass
from pathlib import Path

from _vault_utils import (
    build_file_index,
    build_markdown_index,
    changelog,
    looks_like_mirror_area,
    markdown_report,
    normalize_text,
    parse_links,
    read_text,
    resolve_markdown_target,
    resolve_wikilink_target,
    safe_json_dump,
    scan_files,
    utc_now_iso,
    write_markdown,
)


ARTICLE_PREFIXES = ("a ", "o ", "as ", "os ", "um ", "uma ", "uns ", "umas ")


@dataclass(frozen=True)
class BrokenLink:
    source: str
    target: str
    link_type: str
    source_nested: bool
    source_top_level: str


@dataclass(frozen=True)
class AliasCandidate:
    alias: str
    target_path: str
    match_type: str
    broken_occurrences: int
    source_count: int
    shared_prefix_depth: int
    target_nested: bool


def compact_normalize(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", normalize_text(value))


def is_external_markdown_target(target: str) -> bool:
    stripped = target.strip()
    return bool(re.match(r"^(https?|mailto|obsidian):", stripped, flags=re.IGNORECASE))


def split_frontmatter(text: str) -> tuple[str | None, str]:
    if not text.startswith("---\n"):
        return None, text
    closing = text.find("\n---\n", 4)
    if closing == -1:
        return None, text
    return text[4:closing], text[closing + 5 :]


def parse_aliases(frontmatter: str | None) -> list[str]:
    if not frontmatter:
        return []
    lines = frontmatter.splitlines()
    aliases: list[str] = []
    in_aliases = False
    for line in lines:
        stripped = line.strip()
        if in_aliases:
            if stripped.startswith("- "):
                aliases.append(stripped[2:].strip().strip('"').strip("'"))
                continue
            if stripped and not line.startswith(" "):
                in_aliases = False
        if stripped == "aliases:":
            in_aliases = True
    return [item for item in aliases if item]


def upsert_aliases(text: str, aliases_to_add: list[str]) -> tuple[str, list[str]]:
    frontmatter, body = split_frontmatter(text)
    existing_aliases = parse_aliases(frontmatter)
    existing_norm = {normalize_text(item) for item in existing_aliases}
    additions = [item for item in aliases_to_add if normalize_text(item) not in existing_norm]
    if not additions:
        return text, []

    if frontmatter is None:
        new_frontmatter_lines = ["aliases:"]
        new_frontmatter_lines.extend(f'  - "{item}"' for item in additions)
        new_text = "---\n" + "\n".join(new_frontmatter_lines) + "\n---\n" + body.lstrip("\n")
        return new_text, additions

    lines = frontmatter.splitlines()
    alias_index = None
    insert_index = len(lines)
    for index, line in enumerate(lines):
        if line.strip() == "aliases:":
            alias_index = index
            insert_index = index + 1
            while insert_index < len(lines) and lines[insert_index].startswith("  - "):
                insert_index += 1
            break

    if alias_index is None:
        lines.append("aliases:")
        lines.extend(f'  - "{item}"' for item in additions)
    else:
        lines[insert_index:insert_index] = [f'  - "{item}"' for item in additions]

    new_frontmatter = "\n".join(lines)
    new_text = f"---\n{new_frontmatter}\n---\n{body.lstrip(chr(10))}"
    return new_text, additions


def shared_prefix_depth(path_a: str, path_b: str) -> int:
    parts_a = Path(path_a).parts
    parts_b = Path(path_b).parts
    depth = 0
    for left, right in zip(parts_a, parts_b):
        if normalize_text(left) != normalize_text(right):
            break
        depth += 1
    return depth


def collect_broken_links(root: Path) -> tuple[list[BrokenLink], dict[str, dict[str, object]], dict[str, str], dict[str, str]]:
    files, _ = scan_files(root)
    markdown_files = [record for record in files if record.extension == ".md"]
    markdown_set = {record.relative_path for record in markdown_files}
    all_paths = {record.relative_path for record in files}
    markdown_index = build_markdown_index(markdown_files)
    file_index = build_file_index(files)
    metadata = {
        record.relative_path: {
            "nested": record.in_nested_subvault,
            "top_level_area": record.top_level_area,
            "path": record.path,
        }
        for record in markdown_files
    }
    stem_by_path = {record.relative_path: Path(record.relative_path).stem for record in markdown_files}
    title_by_path = {}
    alias_by_normalized: dict[str, list[str]] = defaultdict(list)
    alias_by_compact: dict[str, list[str]] = defaultdict(list)
    for record in markdown_files:
        text = read_text(record.path)
        frontmatter, _ = split_frontmatter(text)
        for alias in parse_aliases(frontmatter):
            normalized = normalize_text(alias)
            compact = compact_normalize(alias)
            if normalized:
                alias_by_normalized[normalized].append(record.relative_path)
            if compact:
                alias_by_compact[compact].append(record.relative_path)
        heading_match = re.search(r"^#\s+(.+)$", text, flags=re.MULTILINE)
        title_by_path[record.relative_path] = heading_match.group(1).strip() if heading_match else Path(record.relative_path).stem

    broken_links: list[BrokenLink] = []
    for record in markdown_files:
        text = read_text(record.path)
        wiki_links, markdown_links = parse_links(text)
        for target in wiki_links:
            candidates = resolve_wikilink_target(target, record.path, root, markdown_index, file_index)
            resolved = next((item for item in candidates if item in all_paths), None)
            if not resolved:
                clean_target = target.split("|", 1)[0].split("#", 1)[0].strip()
                normalized = normalize_text(clean_target)
                compact = compact_normalize(clean_target)
                alias_matches = sorted(set(alias_by_normalized.get(normalized, [])))
                if len(alias_matches) != 1 and compact:
                    alias_matches = sorted(set(alias_by_compact.get(compact, [])))
                if len(alias_matches) == 1:
                    resolved = alias_matches[0]
            if not resolved:
                broken_links.append(
                    BrokenLink(
                        source=record.relative_path,
                        target=target,
                        link_type="wikilink",
                        source_nested=record.in_nested_subvault,
                        source_top_level=record.top_level_area,
                    )
                )
        for target in markdown_links:
            if is_external_markdown_target(target):
                continue
            resolved = resolve_markdown_target(target, record.path, root)
            if not resolved or resolved not in all_paths:
                broken_links.append(
                    BrokenLink(
                        source=record.relative_path,
                        target=target,
                        link_type="markdown",
                        source_nested=record.in_nested_subvault,
                        source_top_level=record.top_level_area,
                    )
                )
    return broken_links, metadata, stem_by_path, title_by_path


def build_alias_candidates(
    broken_links: list[BrokenLink],
    metadata: dict[str, dict[str, object]],
    stem_by_path: dict[str, str],
    title_by_path: dict[str, str],
) -> list[AliasCandidate]:
    non_nested_paths = [path for path, item in metadata.items() if not item["nested"]]
    by_article_variant: dict[str, list[str]] = defaultdict(list)
    by_compact_variant: dict[str, list[str]] = defaultdict(list)

    for path in non_nested_paths:
        stem = stem_by_path[path]
        title = title_by_path[path]
        candidates = {stem, title}
        for raw in list(candidates):
            normalized = normalize_text(raw)
            compact = compact_normalize(raw)
            if compact:
                by_compact_variant[compact].append(path)
            for prefix in ARTICLE_PREFIXES:
                if normalized.startswith(prefix):
                    without_article = normalized[len(prefix) :].strip()
                    if without_article:
                        by_article_variant[without_article].append(path)

    grouped_targets = Counter(link.target.strip() for link in broken_links if link.target.strip())
    sources_by_target: dict[str, set[str]] = defaultdict(set)
    for link in broken_links:
        target = link.target.strip()
        if target:
            sources_by_target[target].add(link.source)

    results: list[AliasCandidate] = []
    for target, occurrences in grouped_targets.items():
        normalized_target = normalize_text(target.split("|", 1)[0].split("#", 1)[0].strip())
        compact_target = compact_normalize(target.split("|", 1)[0].split("#", 1)[0].strip())
        article_matches = sorted(set(by_article_variant.get(normalized_target, [])))
        compact_matches = sorted(set(by_compact_variant.get(compact_target, [])))

        match_type = ""
        matches: list[str] = []
        if len(article_matches) == 1:
            match_type = "article-prefix"
            matches = article_matches
        elif len(article_matches) == 0 and len(compact_matches) == 1:
            match_type = "punctuation-normalization"
            matches = compact_matches
        else:
            continue

        target_path = matches[0]
        source_paths = sources_by_target[target]
        prefix_depth = max(shared_prefix_depth(source_path, target_path) for source_path in source_paths)
        if prefix_depth < 2:
            continue

        results.append(
            AliasCandidate(
                alias=target,
                target_path=target_path,
                match_type=match_type,
                broken_occurrences=occurrences,
                source_count=len(source_paths),
                shared_prefix_depth=prefix_depth,
                target_nested=bool(metadata[target_path]["nested"]),
            )
        )

    results.sort(
        key=lambda item: (-item.broken_occurrences, item.match_type, item.target_path.lower(), item.alias.lower())
    )
    return results


def compute_connectivity(root: Path) -> tuple[dict[str, int], dict[str, int], dict[str, int], dict[str, str]]:
    files, _ = scan_files(root)
    markdown_files = [record for record in files if record.extension == ".md"]
    markdown_set = {record.relative_path for record in markdown_files}
    all_paths = {record.relative_path for record in files}
    markdown_index = build_markdown_index(markdown_files)
    file_index = build_file_index(files)
    incoming = Counter()
    outgoing = Counter()
    top_level = {record.relative_path: record.top_level_area for record in markdown_files}

    for record in markdown_files:
        text = read_text(record.path)
        wiki_links, markdown_links = parse_links(text)
        outgoing[record.relative_path] = len(wiki_links) + len(markdown_links)
        for target in wiki_links:
            candidates = resolve_wikilink_target(target, record.path, root, markdown_index, file_index)
            resolved = next((item for item in candidates if item in all_paths), None)
            if resolved and resolved in markdown_set:
                incoming[resolved] += 1
        for target in markdown_links:
            resolved = resolve_markdown_target(target, record.path, root)
            if resolved and resolved in markdown_set:
                incoming[resolved] += 1
    orphan_scores = {path: incoming[path] * 2 + outgoing[path] for path in markdown_set}
    return dict(incoming), dict(outgoing), orphan_scores, top_level


def strategic_backlink_candidates(
    metadata: dict[str, dict[str, object]],
    title_by_path: dict[str, str],
    incoming: dict[str, int],
    outgoing: dict[str, int],
) -> list[dict[str, object]]:
    candidates: list[dict[str, object]] = []
    non_nested_paths = [path for path, item in metadata.items() if not item["nested"]]
    hubs = [
        path
        for path in non_nested_paths
        if incoming.get(path, 0) >= 8 and not looks_like_mirror_area(path)
    ]
    orphans = [
        path
        for path in non_nested_paths
        if incoming.get(path, 0) == 0 and outgoing.get(path, 0) >= 6 and not looks_like_mirror_area(path)
    ]
    for orphan in orphans:
        orphan_parts = Path(orphan).parts
        area_hubs = [path for path in hubs if Path(path).parts[:2] == orphan_parts[:2]]
        best_hub = None
        best_score = -1
        for hub in area_hubs:
            score = shared_prefix_depth(orphan, hub) * 10 + incoming.get(hub, 0)
            if score > best_score:
                best_score = score
                best_hub = hub
        if not best_hub:
            continue
        candidates.append(
            {
                "orphan_path": orphan,
                "orphan_title": title_by_path[orphan],
                "orphan_outgoing": outgoing.get(orphan, 0),
                "suggested_hub": best_hub,
                "hub_title": title_by_path[best_hub],
                "hub_incoming": incoming.get(best_hub, 0),
                "shared_prefix_depth": shared_prefix_depth(orphan, best_hub),
            }
        )
    candidates.sort(
        key=lambda item: (-item["shared_prefix_depth"], -item["hub_incoming"], -item["orphan_outgoing"], item["orphan_path"].lower())
    )
    return candidates[:20]


def apply_safe_aliases(root: Path, alias_candidates: list[AliasCandidate]) -> list[dict[str, object]]:
    grouped: dict[str, list[AliasCandidate]] = defaultdict(list)
    for candidate in alias_candidates:
        if candidate.target_nested:
            continue
        if candidate.match_type not in {"article-prefix", "punctuation-normalization"}:
            continue
        grouped[candidate.target_path].append(candidate)

    applied: list[dict[str, object]] = []
    for relative_path, candidates in grouped.items():
        full_path = root / relative_path
        original = read_text(full_path)
        aliases = sorted({item.alias for item in candidates}, key=lambda value: (normalize_text(value), value))
        updated, additions = upsert_aliases(original, aliases)
        if not additions:
            continue
        full_path.write_text(updated, encoding="utf-8")
        applied.append(
            {
                "path": relative_path,
                "aliases_added": additions,
                "link_occurrences_repaired": sum(
                    item.broken_occurrences for item in candidates if item.alias in additions
                ),
            }
        )
    applied.sort(key=lambda item: item["path"].lower())
    return applied


def main() -> int:
    parser = argparse.ArgumentParser(description="Planeja e aplica reparos seguros de links em vault Obsidian.")
    parser.add_argument("--root", default=".")
    parser.add_argument("--plan-out", default="reports/07-link-repair-plan.md")
    parser.add_argument("--results-out", default="reports/07-link-repair-results.md")
    parser.add_argument("--log-out", default="logs/07-link-repair.md")
    parser.add_argument("--manifest-out", default="_staging/07-link-repair-manifest.json")
    parser.add_argument("--apply-safe-fixes", action="store_true")
    args = parser.parse_args()

    root = Path(args.root).resolve()
    generated_at = utc_now_iso()

    initial_broken_links, metadata, stem_by_path, title_by_path = collect_broken_links(root)
    alias_candidates = build_alias_candidates(initial_broken_links, metadata, stem_by_path, title_by_path)
