def common_phrases(text_a: str, text_b: str, limit: int = 5) -> list[str]:
    words_a = token_words(text_a)
    words_b = token_words(text_b)
    phrases_a = token_ngrams(words_a, 4) if len(words_a) >= 4 else set(words_a)
    phrases_b = token_ngrams(words_b, 4) if len(words_b) >= 4 else set(words_b)
    shared = phrases_a & phrases_b
    ranked = sorted(shared, key=lambda item: (-len(item.split()), item))
    return ranked[:limit]


