def build_markdown_index(files: Iterable[FileRecord]) -> dict[str, list[str]]:
    index: dict[str, list[str]] = defaultdict(list)
    for record in files:
        if record.extension != ".md":
            continue
        stem = normalize_text(Path(record.relative_path).stem)
        if stem:
            index[stem].append(record.relative_path)
        index[normalize_text(record.relative_path)] = [record.relative_path]
    return index


def build_file_index(files: Iterable[FileRecord]) -> dict[str, list[str]]:
    index: dict[str, list[str]] = defaultdict(list)
    for record in files:
        variants = {
            normalize_text(record.relative_path),
            normalize_text(record.relative_path.replace("\\", "/")),
            normalize_text(Path(record.relative_path).name),
            normalize_text(Path(record.relative_path).stem),
        }
        for variant in variants:
            if variant:
                index[variant].append(record.relative_path)
    deduped: dict[str, list[str]] = {}
    for key, values in index.items():
        deduped[key] = sorted(dict.fromkeys(values), key=lambda item: item.lower())
    return deduped


