from __future__ import annotations

import json
import os
import re
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path


@dataclass(frozen=True)
class AreaSpec:
    root: Path
    domain_tag: str
    alias_map: dict[str, list[str]]


def quote(value: str) -> str:
    escaped = value.replace("\\", "\\\\").replace('"', '\\"')
    return f'"{escaped}"'


def strip_quotes(value: str) -> str:
    return value.strip().strip('"').strip("'")


def detect_newline(text: str) -> str:
    return "\r\n" if "\r\n" in text else "\n"


def split_frontmatter(text: str) -> tuple[list[str] | None, list[str]]:
    lines = text.splitlines(keepends=True)
    if not lines or lines[0].strip() != "---":
        return None, lines
    end_idx = None
    for idx in range(1, len(lines)):
        if lines[idx].strip() == "---":
            end_idx = idx
            break
    if end_idx is None:
        return None, lines
    return lines[1:end_idx], lines[end_idx + 1 :]


def parse_top_level_key(lines: list[str], key: str) -> tuple[int | None, int | None, list[str] | None]:
    key_re = re.compile(rf"^(?P<indent>\s*){re.escape(key)}:\s*(?P<rest>.*)$")
    for idx, line in enumerate(lines):
        match = key_re.match(line.rstrip("\r\n"))
        if not match:
            continue
        indent = len(match.group("indent"))
        rest = match.group("rest").strip()
        if rest:
            return idx, idx + 1, [rest]
        end = idx + 1
        items: list[str] = []
        item_re = re.compile(r"^\s*-\s*(?P<value>.*)$")
        while end < len(lines):
            candidate = lines[end].rstrip("\r\n")
            if not candidate.strip():
                end += 1
                continue
            current_indent = len(candidate) - len(candidate.lstrip(" "))
            if current_indent <= indent:
                break
            item_match = item_re.match(candidate)
            if item_match:
                items.append(item_match.group("value").strip())
            else:
                items.append(candidate.strip())
            end += 1
        return idx, end, items
    return None, None, None


def render_list_block(key: str, values: list[str], newline: str) -> list[str]:
    return [f"{key}:{newline}"] + [f"  - {quote(value)}{newline}" for value in values]


def add_list_key(lines: list[str], key: str, values: list[str], newline: str) -> tuple[list[str], bool]:
    start, end, items = parse_top_level_key(lines, key)
    if start is None:
        insert_at = len(lines)
        for idx in range(len(lines) - 1, -1, -1):
            if lines[idx].strip() == "---":
                insert_at = idx
                break
        block = render_list_block(key, values, newline)
        return lines[:insert_at] + block + lines[insert_at:], True

    current = [strip_quotes(item) for item in (items or []) if strip_quotes(item)]
    changed = False
    for value in values:
        if value not in current:
            current.append(value)
            changed = True
    if not changed:
        return lines, False

    rendered = render_list_block(key, current, newline)
    return lines[:start] + rendered + lines[end:], True


def is_excluded(path: Path) -> bool:
    parts = set(path.parts)
    return ".trash" in parts or ".obsidian" in parts or "DiÃ¡rio" in parts or "Diario" in parts


def normalize_rel(path: Path, root: Path) -> str:
    return path.resolve().relative_to(root.resolve()).as_posix()


def update_file(path: Path, domain_tag: str, alias_values: list[str]) -> dict[str, object] | None:
    original = path.read_text(encoding="utf-8", errors="ignore")
    newline = detect_newline(original)
    fm_lines, body_lines = split_frontmatter(original)

    if fm_lines is None:
        new_lines = [f"---{newline}"]
        new_lines.extend(render_list_block("tags", [domain_tag], newline))
        if alias_values:
            new_lines.extend(render_list_block("aliases", alias_values, newline))
        new_lines.append(f"---{newline}")
        new_lines.extend(body_lines)
        new_text = "".join(new_lines)
        if new_text == original:
            return None
        path.write_text(new_text, encoding="utf-8")
        return {"mode": "insert", "added_tags": [domain_tag], "added_aliases": alias_values}

    working = list(fm_lines)
    changed = False
    working, tag_changed = add_list_key(working, "tags", [domain_tag], newline)
    changed = changed or tag_changed
    alias_changed = False
    if alias_values:
        working, alias_changed = add_list_key(working, "aliases", alias_values, newline)
        changed = changed or alias_changed
    if not changed:
        return None

    new_text = "".join([f"---{newline}", *working, f"---{newline}", *body_lines])
    if new_text == original:
        return None
    path.write_text(new_text, encoding="utf-8")
    return {
        "mode": "update",
        "added_tags": [domain_tag] if tag_changed else [],
        "added_aliases": alias_values if alias_changed else [],
    }


